public static void main(Args _args)
{
    Email avaEmail;
    Common avaCommon;

    next main(_args);

    avaCommon = _args.record();

    switch (avaCommon.TableId)
    {
        case tablenum(AgreementHeaderDefault) :
            avaEmail = avaCommon.(fieldnum(AgreementHeaderDefault, AVAEmail));
            break;
    }

    if (avaEmail)
    {
        SysMailerFactory::sendInteractive(new SysMailerMessageBuilder().addTo(avaEmail).getMessage());
    }
}
